from PIL import Image
import numpy as np
import sys

try:
    # Open the image
    image_path = '/home/ctfplayer/ctf_files/extracted/files/Screenshot_From_Manager.PNG'
    img = Image.open(image_path)

    # Basic information
    print(f"Image format: {img.format}")
    print(f"Image size: {img.size}")
    print(f"Image mode: {img.mode}")

    # Check for metadata/EXIF
    exif_data = img._getexif()
    if exif_data:
        print("EXIF data:")
        for tag_id, value in exif_data.items():
            print(f"  {tag_id}: {value}")
    else:
        print("No EXIF data found")

    # Check for text chunks in PNG
    if hasattr(img, 'text'):
        print("PNG text chunks:")
        for k, v in img.text.items():
            print(f"  {k}: {v}")
    else:
        print("No PNG text chunks found")

    # Get image statistics
    img_array = np.array(img)
    print(f"Image shape: {img_array.shape}")
    print(f"Image min value: {img_array.min()}")
    print(f"Image max value: {img_array.max()}")
    print(f"Image mean value: {img_array.mean()}")

    # Show a sample of pixel values (top-left corner)
    print("Sample of pixel values (top-left 5x5):")
    if len(img_array.shape) == 3 and img_array.shape[2] >= 3:
        for i in range(min(5, img_array.shape[0])):
            for j in range(min(5, img_array.shape[1])):
                pixel = img_array[i, j]
                if len(pixel) >= 3:
                    print(f"  Pixel ({i},{j}): RGB={pixel[:3]}", end="")
                    if len(pixel) > 3:
                        print(f", Alpha={pixel[3]}")
                    else:
                        print()
                else:
                    print(f"  Pixel ({i},{j}): {pixel}")
    else:
        print("  Image doesn't have RGB channels")

except Exception as e:
    print(f"Error: {e}")
    traceback_info = sys.exc_info()[2]
    print(f"Line: {traceback_info.tb_lineno}")
